const response = $input.first().json;

const content = response?.candidates?.[0]
  ?.content?.parts
  ?.map(part => part.text || "")
  .join("")
  .trim();

if (!content) {
  return [{
    json: {
      success: false,
      error: "Gemini لم يرجع نتيجة نصية",
      finish_reason:
        response?.candidates?.[0]?.finishReason || null
    }
  }];
}

let analysis;

try {
  // تنظيف تنسيق Markdown إن ظهر
  let cleaned = content
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  // حذف المفتاح العربي غير الصحيح الذي ظهر في استجابة Gemini
  cleaned = cleaned.replace(
    /^\s*عبارات_غير_واضحة\s*:\s*\[\s*\]\s*,?\s*$/gm,
    ""
  );

  // إزالة الفواصل الزائدة قبل إغلاق JSON
  cleaned = cleaned.replace(/,\s*([}\]])/g, "$1");

  analysis = JSON.parse(cleaned);

} catch (error) {
  return [{
    json: {
      success: false,
      error: "تعذر قراءة JSON من Gemini",
      details: error.message,
      raw_result: content
    }
  }];
}

// التحقق من التصنيفات
const allowedClassifications = [
  "within_scope",
  "additional_work",
  "needs_clarification"
];

const scopeAssessment = Array.isArray(analysis.scope_assessment)
  ? analysis.scope_assessment.map(item => ({
      item: item.item || "",
      classification: allowedClassifications.includes(item.classification)
        ? item.classification
        : "needs_clarification",
      evidence: item.evidence || "",
      reason: item.reason || ""
    }))
  : [];

return [{
  json: {
    success: true,
    model: response.modelVersion || "Gemini Flash",
    analysis: {
      confirmed_facts: analysis.confirmed_facts || [],
      missing_information: analysis.missing_information || [],
      ambiguities: analysis.ambiguities || [],
      risks: analysis.risks || [],
      scope_assessment: scopeAssessment,
      suggested_questions: analysis.suggested_questions || [],
      suggested_client_message:
        analysis.suggested_client_message || ""
    }
  }
}];
